// Reuse a completed synthetic chain for these two checks: native recovery is
// read-only, and the copied metadata isolates review/epoch mutations from it.
async function agencyBindingChecks(existingRoot,probeRoot=mkdtempSync(resolve('.agent-runs/agency-binding-'))) {
 const {harnessCapabilities,callHarnessAdapter}=await import('../server/harness-adapters.mjs');
 const month=await loadHarness(join(existingRoot,'agency-month')),attempt=month.attempts.filter(a=>a.capabilityId==='agency.posting'&&a.result?.executionState==='executed').at(-1);assert.ok(attempt);
 const feedback=JSON.parse(readFileSync(attempt.request.feedbackPath,'utf8')),blank=join(probeRoot,'blank-reviewer.json');writeFileSync(blank,JSON.stringify({...feedback,reviewer:'   '}));
 const observed=await callHarnessAdapter({...attempt,phase:'query',scope:month.meta.scope,request:{...attempt.request,feedbackPath:blank},priorResult:undefined,codeDigest:harnessCapabilities().get('agency.posting').codeDigest});assert.equal(observed.applied,true,'the committed operation is still a known historical write');assert.equal(observed.confirmationCurrent,false,'missing original response cannot bless an empty replacement reviewer');
 const state=join(probeRoot,'year-state');cpSync(join(existingRoot,'agency-year'),state,{recursive:true});const saved=await loadHarness(state),yearTask={...saved.tasks.find(t=>t.taskId==='year')};delete yearTask.externalDependencies;await planHarness(state,[yearTask]);
 const call=async()=>{const t=(await inspectHarness(state)).tasks[0];return runHarnessTask(state,{taskId:t.taskId,dependencyDigest:t.dependencyDigest});};
 const baseline=await call();assert.equal(baseline.status,'executed',JSON.stringify(baseline));let view=await inspectHarness(state);await feedbackHarness(state,{taskId:yearTask.taskId,targetVersion:baseline.receipt.targetVersion,dependencyDigest:view.tasks[0].dependencyDigest,decision:'accept',reason:'Synthetic isolated bridge-code binding check',reviewer:'SYNTHETIC-HUMAN-ACCOUNTANT',evidenceRefs:[]});
 const cap=harnessCapabilities().get('agency.annual-calculation');assert.ok(cap.traceReferences.some(ref=>ref.locator==='harness-store.mjs'),'bridge imports must participate, not only the worker file');const epoch=(await loadHarness(state)).capabilityEpochs.get(cap.capabilityId);assert.equal((await inspectHarness(state)).tasks[0].reviewState,'accepted');
 const worker=resolve('server/harness-domain-worker.mjs'),original=readFileSync(worker);
 try {
  writeFileSync(worker,Buffer.concat([original,Buffer.from('\n// Synthetic observed bridge change; restored exactly in finally.\n')]));assert.equal(harnessCapabilities().get(cap.capabilityId).codeDigest,cap.codeDigest,'preserve the native business codeDigest');view=await inspectHarness(state);assert.equal(view.tasks[0].executionState,'stale');assert.equal(view.tasks[0].reviewState,'stale');assert.notEqual((await loadHarness(state)).capabilityEpochs.get(cap.capabilityId).codeTraceDigest,epoch.codeTraceDigest);
 } finally {writeFileSync(worker,original);}
 assert.ok(readFileSync(worker).equals(original));view=await inspectHarness(state);assert.equal(view.tasks[0].executionState,'stale');assert.equal(view.tasks[0].reviewState,'stale','restored bridge bytes never revive the old accountant acceptance');const after=(await loadHarness(state)).capabilityEpochs.get(cap.capabilityId);assert.equal(after.codeTraceDigest,epoch.codeTraceDigest);assert.notEqual(after.epoch,epoch.epoch);
 const fresh=await call();assert.equal(fresh.status,'executed');assert.notEqual(fresh.receipt.targetVersion,baseline.receipt.targetVersion);assert.equal((await inspectHarness(state)).tasks[0].reviewState,'pending');console.log('PASS agency binding checks: empty reviewer stays non-current after lost response; native digest preserved while transitive bridge trace epochs prevent accepted-result ABA revival; explicit read recomputation remains pending. Artifacts: '+probeRoot);
}

